function clean(t){return String(t||'').replace(/```json/gi,'').replace(/```/g,'').trim();}
function num(v){ if(v===null||v===undefined||v==='') return null; const n=parseFloat(String(v).replace(/,/g,'')); return Number.isFinite(n)?n:null; }
// Recuadro [y0, x0, y1, x1] (0-1000) de cada dato en la foto. La app los usa
// para "Ver en la foto"; se descartan los mal formados.
const BOX_KEYS = { total: 'total', subtotal: 'subtotal', itbis: 'itbis', ncf: 'ncf', rnc_emisor: 'rncEmisor', rncEmisor: 'rncEmisor', fecha: 'fecha' };
function boxes(src){
  if(!src || typeof src !== 'object') return null;
  const out = {};
  Object.keys(BOX_KEYS).forEach(function(k){
    const b = src[k];
    if(!Array.isArray(b) || b.length !== 4) return;
    const v = b.map(function(n){ return Math.round(Number(n)); });
    if(!v.every(function(n){ return Number.isFinite(n) && n >= 0 && n <= 1000; })) return;
    if(v[0] >= v[2] || v[1] >= v[3]) return;
    out[BOX_KEYS[k]] = v;
  });
  return Object.keys(out).length ? out : null;
}
function bool(v){ if(v===true||v===false) return v; const s=String(v===null||v===undefined?'':v).trim().toLowerCase(); if(s==='si'||s==='sí'||s==='true') return true; if(s==='no'||s==='false') return false; return null; }
let raw='';
try {
  const item = $input.first().json;
  raw = (item && item.candidates && item.candidates[0] && item.candidates[0].content && item.candidates[0].content.parts && item.candidates[0].content.parts[0] && item.candidates[0].content.parts[0].text)
     || (item && item.content && item.content.parts && item.content.parts[0] && item.content.parts[0].text)
     || item.text || item.response || JSON.stringify(item);
  const data = JSON.parse(clean(raw));
  const items = Array.isArray(data.items) ? data.items.map(function(it){ return { descripcion: (it && (it.descripcion || it.nombre)) || null, cantidad: num(it && it.cantidad), precio: num(it && it.precio) }; }) : [];
  return [{ json: { ok:true, emisor: data.emisor ?? null, rncEmisor: data.rnc_emisor ?? null, cliente: data.cliente ?? null, rncCliente: data.rnc_cliente ?? null, ncf: data.ncf ?? null, fecha: data.fecha ?? null, subtotal: num(data.subtotal), itbis: num(data.itbis), total: num(data.total), descuento: num(data.descuento), propina: num(data.propina), exento: num(data.exento), itbisIncluido: bool(data.itbis_incluido ?? data.itbisIncluido), concepto: data.concepto ?? null, categoria: data.categoria ?? null, notas: data.notas ?? null, items: items, boxes: boxes(data.boxes) } }];
} catch (e) {
  return [{ json: { ok:false, error: e.message, raw: raw } }];
}

