const prompt = 'Eres experto en extraer datos de facturas o recibos de compra. Analiza todas las paginas del comprobante y devuelve UNICAMENTE un JSON valido, sin texto adicional ni bloques de codigo. Si un dato no aparece, usa null. Campos: {"emisor": nombre de la tienda o proveedor, "rnc_emisor": RNC o identificacion fiscal del emisor, "cliente": nombre del cliente o comprador si aparece, "rnc_cliente": RNC del cliente si aparece, "ncf": numero de comprobante fiscal, "fecha": fecha en formato YYYY-MM-DD, "subtotal": numero sin simbolos (el monto ANTES de descuento e ITBIS cuando asi viene impreso), "descuento": monto total del descuento sin simbolos o null si no hay, "propina": monto de la propina legal / Ley 10% / servicio sin simbolos o null si no hay, "exento": monto de los articulos exentos de ITBIS sin simbolos o null si no se muestra, "itbis": numero del impuesto sin simbolos, "itbis_incluido": true si los precios o el subtotal ya incluyen el ITBIS (dice "ITBIS incluido" o el subtotal es igual al total), false si el ITBIS se suma aparte, null si no se sabe, "total": numero sin simbolos, "concepto": descripcion breve general de la compra, "categoria": una de Materiales/Transporte/Comida/Herramientas/Mano de obra/Combustible/Otros, "notas": notas u observaciones escritas en el documento si las hay, "items": lista de articulos comprados (maximo 30) donde cada uno es {"descripcion": nombre corto del articulo, "cantidad": numero, "precio": precio total del articulo sin simbolos}, "boxes": {"total", "subtotal", "itbis", "ncf", "rnc_emisor", "fecha"} donde cada uno es el recuadro del valor en la imagen como [y_min, x_min, y_max, x_max] con enteros normalizados de 0 a 1000; el recuadro cubre solo el valor (no su etiqueta); usa null para el dato que no veas, y "boxes": null si el comprobante es PDF o tiene varias paginas}';
return [{ json: { geminiBody: { contents: [{ role: 'user', parts: [{ text: prompt }, { inlineData: { mimeType, data } }] }], generationConfig: { maxOutputTokens: 4096, responseMimeType: 'application/json' } } } }];
